def build_agent(sandbox):
    # Optimized beam structure for stability and buoyancy
    beam_w = 0.62  # Width between 0.15m and 2.0m
    beam_h = 0.8   # Height between 0.15m and 2.0m
    density = 40.0  # Sufficient density for deep channel buoyancy

    # Ensure all beams are within the build zone (x=[2.0, 8.0])
    centers_x = [3.0 + i * 0.62 for i in range(9)]  # 9 beams spaced 0.62m apart
    y_center = 1.5 + beam_h / 2  # Higher y-position for better buoyancy

    bodies = []
    for x in centers_x:
        b = sandbox.add_beam(x, y_center, beam_w, beam_h, angle=0, density=density)
        sandbox.set_material_properties(b, restitution=0.05)  # Low bounce for stability
        bodies.append(b)

    # Connect beams with rigid joints for structural integrity
    for i in range(8):
        anchor_x = (centers_x[i] + centers_x[i + 1]) / 2
        sandbox.add_joint(bodies[i], bodies[i + 1], (anchor_x, y_center), type='rigid')

    return bodies[-1]


def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    # Stop if the front has reached the target
    if front_x >= target_x + 0.1:
        for b in sandbox.bodies:
            if b.active:
                b.linearVelocity = (0, 0)
                b.angularVelocity = 0
        return

    # Environmental conditions
    in_water = front_x >= 10.0
    in_danger_zone = (12.0 <= front_x <= 22.0)
    in_deep_channel = (16.5 <= front_x <= 19.5)

    # Apply thrust to all beams during build phase (front_x < 10.0)
    if front_x < 10.0:
        # Apply thrust to all beams every 100 steps (reduced cooldown)
        if step_count % 100 == 0:
            for b in sandbox.bodies:
                if b.active:
                    fx = 520.0  # Max thrust per component
                    fy = 0.0
                    if in_danger_zone or in_deep_channel:
                        fy = 520.0  # Apply lift force
                    sandbox.apply_force(b, fx, fy, step_count=step_count)

    # Apply lift force in danger zone and deep channel to front beams
    if in_danger_zone or in_deep_channel:
        for b in reversed(sandbox.bodies):
            if b.active and b.position.x >= 10.0:
                fx = 0.0
                fy = 520.0  # Lift force for deep channel
                sandbox.apply_force(b, fx, fy, step_count=step_count)
                break
